import { VNode } from '@stencil/core';

/**
 * @locale {en} Processes the VNode children of a functional component and organizes them
 * into a Record of named slots.
 * @locale {zh} 处理函数式组件的 VNode 子节点，并将它们组织成命名插槽的记录对象。
 * @param children The array of VNodes passed to the functional component.
 * @param slotsFromProps The Record of slots passed as props to the component.
 * @param removeSlotAttr Whether to remove the 'slot' attribute from the VNodes. Defaults to true.
 * @returns An object where keys are slot names and values are arrays of VNodes.
 */
export function mapVChildrenToSlots(
  children: VNode[],
  slotsFromProps: Record<string, VNode[]>,
  removeSlotAttr = true,
): Record<string, VNode[]> {
  const slots = Object.keys(slotsFromProps).reduce<Record<string, VNode[]>>((acc, key) => {
    acc[key] = slotsFromProps[key]!;
    if (removeSlotAttr) {
      acc[key].forEach((slot) => {
        delete slot.$attrs$.slot;
      });
    }
    return acc;
  }, {});

  // Ensure children is an array before trying to process it
  if (!Array.isArray(children)) {
    return slots;
  }

  for (const child of children) {
    // Get the slot name from the VNode's attributes. Default to 'default'.
    const slotName = child.$attrs$.slot || 'default';
    if (removeSlotAttr) {
      // delete slot attr
      delete child.$attrs$.slot;
    }
    if (slots[slotName]) {
      slots[slotName].push(child);
    } else {
      slots[slotName] = [child];
    }
  }
  return slots;
}
