import { Fragment, h, VNode } from '@stencil/core';
import { mapVChildrenToSlots } from '@src/shared/vdom';
import { MenuItemBase, MenuItemPopoverProps, Value } from './types';
import { filterDataAttrs } from './utils';
import { CSSProperties, isEventFromTopLayerSurface } from '@src/shared/dom';
import { JSXBase } from '@stencil/core/internal';
import { KsIconCheckMarkSmall, KsIconHelp } from '@fe-infra/keystone-icons-stencil';

const prefix = 'menu-item-base';

const isButtonOrLinkElement = (target: EventTarget): boolean => {
  const { tagName } = (target as Element) || {};
  return (
    ['BUTTON', 'A', 'KS-BUTTON', 'KS-LINK', 'KS-ICON-BUTTON'].includes(tagName) ||
    (['KS-BUTTON-', 'KS-LINK-', 'KS-ICON-BUTTON-'].some((prefix) => tagName?.startsWith(prefix)) &&
      !tagName?.startsWith('KS-BUTTON-GROUP'))
  );
};

const isEventFromButtonOrLinkDescendant = (event: Event, boundary: EventTarget | null): boolean => {
  const path = event.composedPath?.() || [];
  const end = boundary ? path.indexOf(boundary) : -1;
  return path.slice(0, end >= 0 ? end : path.length).some(isButtonOrLinkElement);
};

export interface MenuItemBaseProps<T = MenuItemBase> {
  classes?: {
    [className: string]: boolean;
  };
  style?: CSSProperties;
  /** Controls whether the menu item supports multiple selection. When true, the menu item allows multiple selections. */
  multiple: boolean;
  /** Whether to hide the checkmark of the menu item. */
  hideCheckmark?: boolean;
  /** The value of the menu item. */
  value: Value;
  /** Controls whether the menu item is disabled. When true, the menu item is not interactive. */
  disabled?: boolean;
  /** Controls whether the menu item is selectable. When true, the menu item is selectable. */
  selectable?: boolean;
  /** Controls whether the menu item is checked. When true, the menu item is checked. */
  checked: boolean;
  /**
   * @style style prop
   * Controls whether the menu item is active. When true, the menu item will use active style.
   */
  active?: boolean;
  /** Controls whether the menu item is indeterminate. When true, the menu item is indeterminate. */
  indeterminate?: boolean;
  /** The content to display in the menu item. */
  label?: string;
  /** The description to display in the menu item. */
  description?: string;
  /** The help content to display in the menu item. */
  helpContent?: string;
  /** The highlight range of the menu item, [start, end]. */
  highlight: [number, number] | null;
  /** The click event of the menu item. */
  onClick?: (value: Value, e: PointerEvent) => void;
  /** The check event of the menu item. */
  onCheck?: (e: PointerEvent) => void;
  /** The popover props of the menu item. */
  popover?: Partial<MenuItemPopoverProps<T>>;
  /** The mouse enter event of the menu item. */
  onMouseEnter?: JSXBase.DOMAttributes<HTMLLIElement>['onMouseEnter'];
  /** The mouse leave event of the menu item. */
  onMouseLeave?: JSXBase.DOMAttributes<HTMLLIElement>['onMouseLeave'];
  /** The slots of the menu item. Priority is higher than the slots from children. */
  slots?: {
    label?: VNode[];
    description?: VNode[];
    popover?: VNode[];
    helpContent?: VNode[];
    before?: VNode[];
    prefix?: VNode[];
    suffix?: VNode[];
    render?: VNode[];
  };

  /** Parameters carried in automatic tracking report */
  dataAttrs?: Record<`data-${string}`, string | boolean>;
}

export const KsMenuItemBase = <T = MenuItemBase>(
  {
    classes: className,
    style,
    multiple,
    hideCheckmark,
    value,
    disabled = false,
    selectable = true,
    checked,
    active = false,
    indeterminate = false,
    label = '',
    description,
    helpContent,
    highlight,
    onClick,
    onCheck,
    popover,
    onMouseEnter,
    onMouseLeave,

    slots = {},
    dataAttrs = {},
  }: MenuItemBaseProps<T>,
  childNodes: VNode[],
) => {
  const {
    label: labelSlot,
    description: descriptionSlot,
    popover: popoverSlot,
    helpContent: helpContentSlot,
    before: beforeSlot,
    prefix: prefixSlot,
    suffix: suffixSlot,
    after: afterSlot,
    render: renderSlot,
  } = mapVChildrenToSlots(childNodes, slots);

  const renderMenuItemContent = (): VNode => {
    let content: VNode | VNode[];
    if (labelSlot) {
      content = labelSlot;
    } else if (highlight) {
      const [start, end] = highlight;
      content = (
        <ks-text
          ellipsis={{
            maxLines: 1,
            tooltip: !popover,
          }}
          variant="bodySm"
        >
          {start > 0 && <span>{label.slice(0, start)}</span>}
          <span data-highlight>{label.slice(start, end)}</span>
          {end < label.length && <span>{label.slice(end)}</span>}
        </ks-text>
      );
    } else {
      content = (
        <ks-text
          ellipsis={{
            maxLines: 1,
            tooltip: !popover,
          }}
          variant="bodySm"
        >
          {label}
        </ks-text>
      );
    }

    // helpContent
    content = (
      <div
        class={{
          [`${prefix}__content--text--label`]: true,
        }}
      >
        {content}
        {(helpContent || helpContentSlot) && (
          <ks-tooltip size="md">
            <KsIconHelp />
            <div slot="content">
              {helpContent}
              {helpContentSlot}
            </div>
          </ks-tooltip>
        )}
      </div>
    );

    return (
      <div class={`${prefix}__content`}>
        {prefixSlot}
        <div class={`${prefix}__content--text`}>
          {content}
          {typeof description === 'string' ? (
            <ks-text
              ellipsis={{
                maxLines: 2,
                tooltip: !popover,
              }}
              variant="labelSm"
              class={`${prefix}__content--desc`}
            >
              {description}
            </ks-text>
          ) : (
            descriptionSlot && <div class={`${prefix}__content--desc`}>{descriptionSlot}</div>
          )}
        </div>
      </div>
    );
  };

  const handleItemClick = (e: PointerEvent) => {
    if (
      disabled ||
      !selectable ||
      isEventFromTopLayerSurface(e, e.currentTarget) ||
      isEventFromButtonOrLinkDescendant(e, e.currentTarget)
    ) {
      return;
    }
    onClick?.(value, e);
  };
  const handleItemCheck = (e: PointerEvent) => {
    if (disabled || !selectable) return;
    onCheck?.(e);
  };

  const classes = {
    [`${prefix}`]: true,
    [`${prefix}--active`]: active,
    [`${prefix}--disabled`]: disabled,
    [`${prefix}--static`]: !selectable,
    [`${prefix}--multiple`]: multiple,
    ...className,
  };

  const item = (
    <li
      {...filterDataAttrs(dataAttrs)}
      key={value}
      class={classes}
      onClick={(e) => {
        handleItemClick(e);
      }}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      style={style}
      data-testid={`ks-menu-item-item-xb3yLe-${value}`}
    >
      {renderSlot && renderSlot.length > 0 ? (
        renderSlot
      ) : (
        <Fragment>
          {beforeSlot}
          {!!multiple && (
            <ks-checkbox
              class={`${prefix}__checkbox`}
              checked={checked}
              disabled={disabled}
              indeterminate={indeterminate}
              onClick={handleItemCheck}
              data-testid="ks-menu-item-item-gg3V1y"
            ></ks-checkbox>
          )}
          {renderMenuItemContent()}

          {suffixSlot}
          {!multiple && !hideCheckmark && checked && <KsIconCheckMarkSmall size="14" />}
          {afterSlot}
        </Fragment>
      )}
    </li>
  );

  if (!popoverSlot && !popover) {
    return item;
  }

  const { render, ...popoverProps } = popover!;

  return (
    <ks-tooltip
      exportparts="content: popupContent"
      class={`${prefix}__tooltip`}
      trigger="hover"
      {...popoverProps}
      key={value}
      data-testid={`ks-menu-item-item-9SBwsP-${value}`}
    >
      {popoverSlot ? (
        <div slot="content">{popoverSlot}</div>
      ) : (
        <ks-text slot="content" variant="bodySm">
          {popover!.content || ''}
        </ks-text>
      )}

      {item}
    </ks-tooltip>
  );
};
