import { h, VNode } from '@stencil/core';
import { CustomRenderFn, MenuItemBase, Value } from '../types';
import { RenderConfig } from '@src/components/ks-virtual-list/types';

/** Get the slot name for a menu item. */
export const getItemSlotNameFromSlotTypeAndValue = (slotType: string, itemValue: Value, ...restValues: Value[]) =>
  `slot-item-${slotType}-${itemValue}${restValues.map((v) => `-${v}`).join('')}`;

/**
 * 在渲染菜单项目时，根据项目值和其他值生成插槽名称，用于渲染菜单项目内部的插槽。
 * <MenuItemBase>
 *    {...renderItemSlots(item, ...restValues)}
 * </MenuItemBase>
 * Render the slots for a menu item.
 */
export const renderItemSlots = (item: MenuItemBase, ...restValues: Value[]): VNode[] =>
  [
    item.prefix &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('prefix', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('prefix', item.value, ...restValues),
        slot: 'prefix',
      }),
    item.suffix &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('suffix', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('suffix', item.value, ...restValues),
        slot: 'suffix',
      }),
    item.label &&
      typeof item.label === 'function' &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('label', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('label', item.value, ...restValues),
        slot: 'label',
      }),
    item.description &&
      typeof item.description === 'function' &&
      h(
        'slot',
        {
          name: getItemSlotNameFromSlotTypeAndValue('description', item.value, ...restValues),
          key: getItemSlotNameFromSlotTypeAndValue('description', item.value, ...restValues),
          slot: 'description',
        },
        [
          h('div', {
            style: { 'min-height': '16px' },
          }),
        ],
      ),
    item.helpContent &&
      typeof item.helpContent === 'function' &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('helpContent', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('helpContent', item.value, ...restValues),
        slot: 'helpContent',
      }),
    item.popover?.render &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('popover', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('popover', item.value, ...restValues),
        slot: 'popover',
      }),
    item.render &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('render', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('render', item.value, ...restValues),
        slot: 'render',
      }),
  ].filter(Boolean) as VNode[];

/** Render the dynamic children for a menu item. */
export const renderDynamicChildren = <T extends MenuItemBase<T>>(
  item: T,
  index: number,
  wrapWithSlot: (slotName: string, children: unknown) => unknown,
  renderConfig?: RenderConfig,
) => {
  const dynamicSlots: Array<unknown> = [];
  const createSlot = (type: string, itemValue: Value, renderFn?: CustomRenderFn<T>, ...restProps: Value[]) => {
    const slotName = getItemSlotNameFromSlotTypeAndValue(type, itemValue, ...restProps);
    dynamicSlots.push(wrapWithSlot(slotName, renderFn?.(item, renderConfig)));
  };

  const createSlotForDropdownMenuItem = (item: T, ...restProps: Value[]) => {
    const slotConfigs = [
      { renderFn: item.prefix, type: 'prefix' },
      { renderFn: item.suffix, type: 'suffix' },
      { renderFn: item.label, type: 'label' },
      { renderFn: item.description, type: 'description' },
      { renderFn: item.helpContent, type: 'helpContent' },
      { renderFn: item.popover?.render, type: 'popover' },
      { renderFn: item.render, type: 'render' },
    ];
    slotConfigs.forEach(({ renderFn, type }) => {
      if (typeof renderFn === 'function') {
        createSlot(type, item.value, renderFn, ...restProps);
      }
    });
  };

  createSlotForDropdownMenuItem(item, index);
  return dynamicSlots;
};

/**
 * 在渲染菜单项目时，根据 item 渲染出透传的插槽数组
 * <ks-xxx>
 *   <MenuItemBase>
 *      {...renderItemSlots(item, ...restValues)}
 *   </MenuItemBase>
 *   {...renderPassThroughSlots(item, ...restValues)}
 * </ks-xxx>
 * Render the slots for a menu item.
 */
export const renderPassThroughSlots = <T extends MenuItemBase<T>>(item: T, ...restValues: Value[]): VNode[] =>
  [
    item.prefix &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('prefix', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('prefix', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('prefix', item.value, ...restValues),
      }),
    item.suffix &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('suffix', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('suffix', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('suffix', item.value, ...restValues),
      }),
    item.label &&
      typeof item.label === 'function' &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('label', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('label', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('label', item.value, ...restValues),
      }),
    item.description &&
      typeof item.description === 'function' &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('description', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('description', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('description', item.value, ...restValues),
      }),
    item.helpContent &&
      typeof item.helpContent === 'function' &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('helpContent', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('helpContent', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('helpContent', item.value, ...restValues),
      }),
    item.popover?.render &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('popover', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('popover', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('popover', item.value, ...restValues),
      }),
    item.render &&
      h('slot', {
        name: getItemSlotNameFromSlotTypeAndValue('render', item.value, ...restValues),
        slot: getItemSlotNameFromSlotTypeAndValue('render', item.value, ...restValues),
        key: getItemSlotNameFromSlotTypeAndValue('render', item.value, ...restValues),
      }),
  ].filter(Boolean) as VNode[];
